from google.cloud import firestore
import os

def get_firestore_client():
    # Initialize Google Cloud Firestore client
    # Environment variable GOOGLE_APPLICATION_CREDENTIALS should be set
    # or the project ID should be explicitly passed if not running in GCP
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    if project_id:
        return firestore.Client(project=project_id)
    else:
        return firestore.Client()

import json

class Document:
    def __init__(self, id: str, data: dict):
        self.id = id
        self.data = data

    def to_dict(self):
        return {"id": self.id, "data": self.data}

    @classmethod
    def from_dict(cls, doc_id: str, doc_data: dict):
        return cls(doc_id, doc_data)

class UpsertDocumentRequest:
    def __init__(self, collection_name: str, document_id: str, document_data: dict):
        self.collection_name = collection_name
        self.document_id = document_id
        self.document_data = document_data

class UpsertDocumentResponse:
    def __init__(self, success: bool, document_id: str, message: str = ""):
        self.success = success
        self.document_id = document_id
        self.message = message

from database_client import get_firestore_client
from database_models import UpsertDocumentRequest, UpsertDocumentResponse

def upsert_document(request: UpsertDocumentRequest) -> UpsertDocumentResponse:
    """
    Upserts a JSON document into Google Cloud Firestore.
    """
    db = get_firestore_client()
    doc_ref = db.collection(request.collection_name).document(request.document_id)

    try:
        doc_ref.set(request.document_data)
        return UpsertDocumentResponse(
            success=True,
            document_id=request.document_id,
            message="Document upserted successfully."
        )
    except Exception as e:
        return UpsertDocumentResponse(
            success=False,
            document_id=request.document_id,
            message=f"Error upserting document: {e}"
        )

